const fs=require('node:fs');
const path=require('node:path');
const examples={
 'bio-diversity-4-plant-cell-tissues-lesson':['У ткани вытянутые одревесневшие клетки без живого содержимого. По ним движется вода. Какая это ткань и почему её строение подходит функции?','Это проводящие элементы ксилемы. Полый просвет уменьшает сопротивление потоку, одревесневшие стенки препятствуют спадению. Ситовидные элементы флоэмы живые и проводят прежде всего растворы органических веществ.'],
 'bio-diversity-4-plant-root-lesson':['После повреждения зоны корневых волосков растение хуже поглощает воду. Почему сохранённая верхушка корня не полностью компенсирует потерю?','Корневые волоски увеличивают площадь контакта с почвенным раствором. Верхушка обеспечивает защиту и рост, но её функция и площадь всасывающей поверхности другие. Восстановление зависит от образования новых участков всасывания.'],
 'bio-diversity-4-plant-root-lesson-2':['У моркови запас расположен в корнеплоде, у картофеля — в клубне. По каким признакам клубень является побегом?','На клубне картофеля есть почки — глазки, связанные с узлами; из них развиваются побеги. Корнеплод включает утолщённые участки корня и у некоторых растений подсемядольного колена. Запасание вещества само по себе не определяет происхождение органа.'],
 'bio-diversity-4-plant-root-lesson-3':['Почему уплотнение переувлажнённой почвы может ухудшать минеральное питание корня?','В почве уменьшается доступ воздуха. Корням труднее получать кислород для клеточного дыхания, уменьшается снабжение активного транспорта энергией. Поэтому наличие растворённых солей ещё не гарантирует их нормального избирательного поглощения.'],
 'bio-diversity-4-plant-shoot-lesson':['Прищипнули верхушечную почку побега, после чего боковые побеги стали расти активнее. Какие структуры дали новые побеги?','Пазушные почки в узлах побега. Удаление верхушки может ослабить её регулирующее влияние на боковые почки. Междоузлие — участок между узлами; листовая пластинка сама по себе не является обычной пазушной почкой.'],
 'bio-diversity-4-plant-shoot-lesson-2':['После кольцевого удаления коры с флоэмой дерево некоторое время сохраняет листья, но корни голодают. Почему?','Сохранённая ксилема ещё проводит воду к листьям. Перерезанная флоэма нарушает перенос сахаров от листьев к корням; корни расходуют запасы и ослабевают. Долговременное повреждение корней затем нарушит и водоснабжение.'],
 'bio-diversity-4-plant-leaf-lesson':['Почему столбчатая ткань листа обычно богата хлоропластами, а губчатая имеет большие межклетники?','Столбчатые клетки эффективно используют падающий свет для фотосинтеза. Межклетники губчатой ткани облегчают перемещение газов между устьицами и клетками. Обе ткани могут фотосинтезировать; различия связаны с преимущественной ролью и расположением.'],
 'bio-diversity-4-plant-leaf-lesson-2':['Почему закрывание устьиц в засуху экономит воду, но может уменьшать образование сахаров?','Снижается выход водяного пара через устьичные щели. Одновременно ограничивается поступление CO₂, необходимого для фотосинтеза. Растение сталкивается с противоречием между сохранением воды и обеспечением фиксации углерода.'],
 'bio-diversity-4-plant-flower-pollination-lesson':['В цветке удалили пыльники, сохранив рыльце, столбик и завязь. Может ли он дать семена после переноса чужой совместимой пыльцы?','Да, если женские структуры и дальнейшее развитие не нарушены. Пыльники производят пыльцу, а семязачатки находятся в завязи. Отсутствие собственных пыльников препятствует получению своей пыльцы, но не обязательно перекрёстному опылению.'],
 'bio-diversity-4-plant-flower-pollination-lesson-2':['У растения мелкие невзрачные цветки, много лёгкой сухой пыльцы и крупные перистые рыльца. Предложите способ опыления и объясните два признака.','Вероятно, ветроопыление. Много лёгкой пыльцы повышает вероятность случайного переноса, а разветвлённые рыльца увеличивают улавливающую поверхность. Яркие венчики и нектар для привлечения животных при таком переносе не обязательны.'],
 'bio-diversity-4-plant-double-fertilization-lesson':['У цветкового растения соматическая клетка имеет 24 хромосомы. Сколько их обычно в спермии, зиготе и эндосперме при стандартном двойном оплодотворении?','В спермии 12, в зиготе 24, в эндосперме 36. Один спермий сливается с яйцеклеткой n, второй — с центральной клеткой с двумя гаплоидными полярными ядрами. Семенная кожура развивается из материнских покровов и имеет 24 хромосомы.'],
 'bio-diversity-4-plant-seed-fruit-lesson':['Почему семя может не прорасти в тёплой воде при полном отсутствии доступа кислорода?','Прорастающему зародышу нужна энергия для роста и мобилизации запасов. Недостаток кислорода ограничивает аэробное дыхание; вода и подходящая температура не заменяют его. Устойчивость к затоплению различается у видов.'],
 'bio-diversity-4-plant-physiology-lesson':['На свету лист выделил в среду 7 условных единиц O₂, а расход на дыхание составил 3. Какова валовая фотосинтетическая выработка в этой модели?','7 + 3 = 10 единиц. Наблюдаемый газообмен — разность образования кислорода при фотосинтезе и его расхода при дыхании. На свету дыхание не прекращается; в темноте фотосинтетическое выделение O₂ прекращается.'],
 'bio-diversity-4-plant-physiology-lesson-2':['Побег изгибается к боковому свету, листья мимозы складываются после прикосновения, эвглена плывёт к свету. Различите три реакции.','Изгиб побега — фототропизм: направление роста связано с направлением света. Складывание мимозы — настия, определяемая устройством органа и изменениями тургора, а не направлением касания. Перемещение всей эвглены — положительный фототаксис.'],
 'bio-diversity-4-plant-algae-mosses-lesson':['Почему крупная морская водоросль может обходиться без настоящих корней и сосудов, а наземному дереву они необходимы?','В воде большая часть поверхности слоевища соприкасается с источниками растворённых веществ; вода поддерживает тело. У дерева корни получают воду из почвы, проводящие ткани переносят её к удалённым органам, механические ткани обеспечивают опору на суше.'],
 'bio-diversity-4-plant-algae-mosses-lesson-2':['Листостебельное растение кукушкина льна имеет n = 10. Какой набор в коробочке на ножке и в спорах?','Коробочка с ножкой относится к спорофиту и имеет 2n = 20. В ней мейоз образует споры n = 10. Зелёное листостебельное растение — гаметофит; его гаметы образуются без редукции уже гаплоидного набора.'],
 'bio-diversity-4-plant-spore-vascular-lesson':['У растения есть корни и проводящие ткани, но вместо семян образуются споры в спороносных колосках. Почему этих данных мало для определения хвоща?','Корни и проводящие ткани отличают сосудистые споровые от типичных мхов, но колоски есть и у ряда плаунов. Для хвоща дополнительно характерны членистые стебли с узлами, мутовками и редуцированными листьями. Определение требует совокупности признаков.'],
 'bio-diversity-4-plant-spore-vascular-lesson-2':['На нижней стороне вайи папоротника находятся сорусы. Что в них образуется и из чего развивается заросток?','В сорусах собраны спорангии; мейоз образует гаплоидные споры. Спора прорастает в гаметофит — заросток с половыми органами. Сорус не является цветком, а спора не равна семени или гамете.'],
 'bio-diversity-4-plant-seed-groups-lesson':['Почему у сосны есть семена, но нет плодов, а для оплодотворения не нужна наружная плёнка воды?','Семязачатки расположены открыто на семенных чешуях, завязи нет, поэтому плод не образуется. Мужской гаметофит развивается из пыльцы, пыльцевая трубка доставляет спермии. Семя и плод — разные структуры.'],
 'bio-diversity-4-plant-seed-groups-lesson-2':['У растения цветок с четырьмя крестообразно расположенными лепестками, шестью тычинками, из которых две короче, и плод стручок. Определите семейство.','Крестоцветные, или Капустные. Диагностична совокупность строения цветка и плода; один признак, например четыре лепестка, не следует считать безошибочным определителем всех растений. Стручок отличается от боба наличием перегородки.'],
 'bio-diversity-4-plant-life-cycles-lesson':['Почему мейоз у папоротника создаёт споры, а у животного участвует в образовании гамет?','У папоротника спорофит 2n образует споры n, из которых митозами развивается гаметофит; уже он образует гаметы. В типичном животном цикле отдельного многоклеточного гаплоидного поколения нет. Роль мейоза устанавливают по жизненному циклу, а не по одному названию клетки.'],
 'bio-zoo-foundations':['Сравните полость тела круглого червя и дождевого червя. Почему это не просвет кишечника?','У круглого червя первичная полость без сплошной собственной мезодермальной выстилки; у кольчатого — вторичная, целом. Полость тела расположена между стенкой тела и органами, а просвет кишечника находится внутри пищеварительной трубки.'],
 'bio-zoo-protists':['Пресноводную инфузорию поместили в среду с несколько большей концентрацией солей, не повреждающую клетку. Почему сократительная вакуоль может работать реже?','Разница осмотических условий уменьшилась, вода медленнее поступает в клетку. Удалять избыток приходится реже. Сократительная вакуоль регулирует прежде всего водный баланс; пищеварительная вакуоль расщепляет пищу.'],
 'bio-zoo-sponges':['Почему остановка движения жгутиков воротничковых клеток губки влияет одновременно на питание и газообмен?','Жгутики создают ток воды через тело. Вода приносит пищевые частицы и кислород, удаляет продукты обмена. У губки нет отдельной кровеносной или дыхательной системы, которая полностью заменила бы этот поток.'],
 'bio-zoo-cnidarians':['Почему гидра может переваривать добычу крупнее одной клетки, хотя у неё нет сквозного кишечника?','Сначала ферменты действуют в кишечной полости и расщепляют добычу внеклеточно. Затем клетки поглощают частицы и завершают пищеварение в вакуолях. Непереваренные остатки выходят через то же отверстие, через которое поступила пища.'],
 'bio-zoo-flatworms':['У планарии нет кровеносной системы. Как форма тела и кишечник облегчают обеспечение клеток веществами?','Уплощение уменьшает расстояние диффузии газов через поверхность. Разветвлённый кишечник приближает перевариваемую пищу к тканям. Эти особенности уменьшают необходимость отдельного транспорта, но ограничивают возможную толщину тела.'],
 'bio-zoo-tapeworm-fluke':['Почему плохо обработанная говядина связана с риском заражения бычьим цепнем, а водные растения и вода — с печёночным сосальщиком?','В мышцах промежуточного хозяина цепня находятся финны, из которых в кишечнике окончательного хозяина развивается взрослый червь. У сосальщика после стадии в моллюске образуются личиночные формы, инцистирующиеся во внешней среде. Пути передачи определяются конкретным циклом, а не словом «паразит».'],
 'bio-zoo-roundworms':['Почему яйца аскариды, только что вышедшие с фекалиями, не описывают весь путь заражения нового хозяина?','Для развития инвазионной стадии яйцам нужны подходящие условия внешней среды. После проглатывания зрелых яиц личинки выходят, мигрируют через ткани и лёгкие и затем возвращаются в кишечник. У аскариды нет обязательного промежуточного хозяина.'],
 'bio-zoo-annelids':['Почему дождевому червю важна влажная кожа, а гидроскелету — замкнутые заполненные жидкостью участки тела?','Кислород растворяется на влажной поверхности и диффундирует через кожу в кровь. Жидкость полости почти несжимаема и служит опорой мышцам: изменение формы сегментов участвует в передвижении. Высыхание одновременно нарушает условия газообмена и состояние тканей.'],
 'bio-zoo-mollusc-plan':['У моллюска есть мантия, мантийная полость, тёрка и широкая мускулистая нога. Как связаны эти структуры с функциями?','Мантия участвует в образовании раковины и ограничивает мантийную полость, связанную с дыханием. Нога обеспечивает передвижение, тёрка соскребает или измельчает пищу. Такая совокупность подходит брюхоногому; у двустворчатых тёрки нет.'],
 'bio-zoo-bivalves-cephalopods':['Почему неподвижный двустворчатый моллюск и активно плавающий головоногий нуждаются в разном устройстве питания и транспорта?','Двустворчатый фильтрует частицы из тока воды, голова и тёрка отсутствуют. Головоногий захватывает добычу щупальцами, имеет развитые органы чувств и замкнутую кровеносную систему, поддерживающую активный образ жизни.'],
 'bio-zoo-arthropod-plan':['Почему членистоногое растёт скачками и особенно уязвимо сразу после линьки?','Наружная кутикула ограничивает увеличение объёма. При линьке старая оболочка сбрасывается, тело увеличивается до затвердевания новой. Мягкая новая оболочка временно хуже защищает от механического воздействия и потери воды.'],
 'bio-zoo-crustaceans':['У рака жабры находятся около оснований грудных конечностей. Чем полезно движение воды в этой области?','Обновляет среду у жабр, поддерживая градиенты кислорода и углекислого газа. Тонкая поверхность жабр обеспечивает обмен, а циркулирующая гемолимфа переносит газы между жабрами и тканями. Одного наличия растворённого кислорода вдали от жабр недостаточно.'],
 'bio-zoo-arachnids':['У взрослого членистоногого четыре пары ходильных ног, нет усиков, тело разделено на головогрудь и брюшко. Почему это не насекомое?','У насекомых три пары грудных ног, одна пара усиков и три основных отдела тела. Указанная совокупность характерна для паукообразных. Признак числа ног учитывают для обозначенной стадии: у некоторых личинок число отличается.'],
 'bio-zoo-insects':['Почему перекрытие дыхалец насекомого нарушит доставку кислорода, хотя гемолимфа продолжает циркулировать?','Воздух поступает через дыхальца в трахеи, которые разветвляются к тканям. У большинства насекомых гемолимфа не является основным переносчиком дыхательных газов. Сохранение её тока не восстанавливает поступление воздуха по перекрытому пути.'],
 'bio-zoo-insect-development':['Личинка бабочки ест листья, имаго питается нектаром; у кузнечика молодая особь похожа на взрослую. Различите типы развития.','У бабочки полное превращение: яйцо, личинка, куколка, имаго. Разные пищевые ресурсы ослабляют конкуренцию стадий. У кузнечика неполное превращение, куколки нет; молодые стадии постепенно приобретают признаки взрослого.'],
 'bio-zoo-chordates':['Почему отсутствие позвоночника у ланцетника не исключает его из хордовых?','Общий признак хордовых — хорда хотя бы на определённом этапе развития, дорсальная нервная трубка и другие особенности плана. Позвоночник характеризует позвоночных, которые составляют лишь часть хордовых. У ланцетника хорда сохраняется во взрослом состоянии.'],
 'bio-zoo-fish':['Почему плавательный пузырь облегчает удержание глубины, но не является обязательным признаком всех рыб?','Изменение его газового объёма меняет плавучесть и затраты на удержание в толще воды. Он характерен для многих костных рыб, но отсутствует у ряда рыб, включая хрящевых. Принадлежность к рыбам нельзя устанавливать только по этому органу.'],
 'bio-zoo-fish-circulation':['Проследите путь крови от желудочка рыбы до его следующего достижения. Где кровь становится богатой кислородом?','Желудочек → сосуды к жабрам → жаберные капилляры → сосуды тела → капилляры органов → вены → предсердие → желудочек. Газообмен происходит в жабрах; через сердце проходит преимущественно венозная кровь. Круг кровообращения один.'],
 'bio-zoo-amphibians':['Почему взрослая лягушка может жить на суше, но её размножение обычно связано с водой?','Лёгкие, конечности и другие признаки позволяют наземную активность; влажная кожа также участвует в дыхании. Икра лишена плотных оболочек амниотического яйца, оплодотворение обычно наружное, а личинка водная. Наземная жизнь взрослой стадии не отменяет требований ранних стадий.'],
 'bio-zoo-amphibian-circulation-development':['У головастика исчезают жабры и развиваются лёгкие. Почему вместе с этим изменяется кровообращение?','Газообмен перемещается к другим поверхностям, возникает лёгочно-кожный путь возврата крови к сердцу и два круга у взрослого животного. Перестройка дыхания требует согласованного изменения транспорта; это не только внешнее исчезновение хвоста.'],
 'bio-zoo-reptiles':['Какие два изменения позволяют пресмыкающимся размножаться вдали от открытого водоёма?','Внутреннее оплодотворение обеспечивает встречу гамет в организме. Зародышевые оболочки и защитные оболочки яйца поддерживают водную среду зародыша и уменьшают высыхание. Сухие роговые покровы взрослого — другая адаптация и не заменяют эти механизмы.'],
 'bio-zoo-amniotic-egg':['Скорлупа защищает яйцо, но имеет поры. Почему сплошная непроницаемая оболочка могла бы нарушить развитие?','Зародыш расходует кислород и выделяет CO₂, поэтому нужен газообмен. Поры и внезародышевые структуры участвуют в этом обмене, одновременно оболочки ограничивают потерю воды. Защита яйца не означает полной изоляции от среды.'],
 'bio-diversity-5-animal-birds-lesson':['Почему полёт птицы нельзя объяснить только наличием крыльев?','Нужны также работа грудных мышц и опора для них, прочность и относительная лёгкость скелета, аэродинамическое оперение, интенсивное дыхание и кровообращение. Крыло создаёт возможность полёта лишь вместе с источником энергии и согласованной работой систем.'],
 'bio-zoo-bird-respiration':['Почему воздушные мешки птицы нельзя считать основным местом газообмена, даже если они меняют объём?','Мешки обеспечивают вентиляцию и направляют потоки воздуха, а основная газообменная поверхность находится в лёгких. Поток через лёгкие поддерживается при вдохе и выдохе. Большой объём полости не означает большой диффузионной поверхности с капиллярами.'],
 'bio-zoo-bird-reproduction':['Чем различаются выводковые и птенцовые птицы и как это связано с заботой о потомстве?','Выводковые птенцы обычно вылупляются зрячими, покрытыми пухом и вскоре передвигаются; птенцовые более беспомощны и дольше остаются в гнезде. Различаются степень развития при вылуплении и способ ухода, а не наличие или отсутствие яйцевых оболочек.'],
 'bio-zoo-mammals':['Почему кит относится к млекопитающим, хотя его форма напоминает рыбу?','Кит дышит лёгкими, выкармливает детёнышей молоком и имеет комплекс признаков млекопитающих. Обтекаемость и плавательные конечности связаны с водной средой и могут возникать у разных линий независимо. Внешнее сходство не заменяет анализ происхождения и строения.'],
 'bio-zoo-mammal-reproduction':['Утконос откладывает яйца, кенгуру рождает очень недоразвитого детёныша, у мыши длительное развитие связано с плацентой. Что объединяет их?','Молочные железы и вскармливание молоком, наряду с другими признаками млекопитающих. Яйцекладка не исключает принадлежности к классу. Отличаются способы и длительность внутриутробного развития и степень развития новорождённого.'],
 'bio-zoo-mammal-orders':['У животного в каждой челюсти по паре крупных постоянно растущих резцов, клыков нет. Какая группа вероятна и с кем её легко спутать?','Вероятны грызуны; резцы приспособлены к сгрызанию, а постоянный рост компенсирует стирание. У зайцеобразных в верхней челюсти есть дополнительная малая пара резцов. Определение опирается на зубную систему, а не только на растительную пищу.'],
 'bio-zoo-compare-coverings-motion':['Сопоставьте слизистую кожу лягушки и роговые покровы ящерицы с потерей воды и газообменом.','Влажная кожа лягушки обеспечивает дополнительный газообмен, но делает организм зависимым от увлажнения. Роговой покров ящерицы уменьшает потерю воды, зато кожное дыхание играет гораздо меньшую роль; основную нагрузку несут лёгкие.'],
 'bio-zoo-compare-respiration':['Почему жабры многих водных животных вне воды работают хуже, хотя в воздухе кислорода больше?','Жаберные лепестки могут спадаться и высыхать, уменьшая доступную поверхность и нарушая условия диффузии. Важна организация газообменной поверхности и её поддержка средой, а не только общее содержание кислорода.'],
 'bio-zoo-compare-circulation':['У птицы и млекопитающего четырёхкамерное сердце. Как это помогает поддерживать высокий обмен?','Правые и левые отделы разделяют венозный и артериальный потоки, ткани получают хорошо насыщенную кислородом кровь. Разделение кругов позволяет поддерживать разные давления в лёгочном и системном русле. Этот комплекс повышает возможности аэробного обмена.'],
 'bio-zoo-compare-excretion-nervous':['Почему трубчатую нервную систему хордового нельзя спутать с брюшной нервной цепочкой кольчатого червя?','У хордовых нервная трубка расположена на спинной стороне относительно хорды и кишечника. У кольчатого червя узлы связаны в брюшную цепочку. Сравнивают положение и общий план, а не только наличие нервных клеток.'],
 'bio-zoo-compare-reproduction-thermoregulation':['Почему теплокровность требует и источника тепла, и способов уменьшить его потери?','Интенсивный обмен образует тепло, а покровы и регуляция сосудов меняют теплоотдачу. Без затрат вещества и энергии изоляция не создаёт тепло; без регулирования отдачи высокая выработка может привести к перегреву.'],
 'bio-zoo-parasites-summary':['В хозяине A паразит размножается половым путём, в хозяине B развивается личинка. Как назвать хозяев и почему их размер не важен?','A — окончательный, B — промежуточный хозяин в данном цикле. Критерий — стадия и способ размножения паразита, а не размер тела хозяина, его положение в пищевой цепи или тяжесть поражения.'],
 'bio-zoo-image-recognition':['На схеме животного обозначены шесть ног на груди, усики и трахеи. Какие признаки дают уверенное определение класса?','Три пары грудных ног и одна пара усиков в сочетании с трахейной системой указывают на насекомое. Членистые конечности определяют более широкую группу членистоногих; число нарисованных крыльев само по себе ненадёжно из-за разнообразия и редукции.']
};

Object.assign(examples, {
 'bio-human-integration':['После начала бега участились дыхание и сердцебиение. Как связаны эти изменения с работой мышц?','Мышцы быстрее расходуют АТФ, кислород и субстраты, выделяют больше CO₂ и тепла. Вентиляция обновляет воздух в альвеолах, кровоток связывает лёгкие с тканями, нервная и гуморальная регуляция согласуют ответ. Одного учащения дыхания без транспорта крови недостаточно.'],
 'bio-human-epithelial':['Почему эпителий тонкой кишки и эпителий кожи устроены по-разному, хотя относятся к одному типу тканей?','В кишке тонкий слой и увеличение поверхности способствуют всасыванию. Многослойность и ороговение наружного эпителия кожи обеспечивают защиту от повреждения и потери воды. Общи тесное расположение клеток и малая доля межклеточного вещества.'],
 'bio-human-connective':['Почему кровь, хрящ и кость относят к соединительным тканям при столь разной твёрдости?','Для них характерны клетки и выраженное межклеточное вещество. У крови оно жидкое, у хряща упругое, у кости минерализованное. Свойства матрикса соответствуют транспорту, амортизации или опоре; принадлежность к ткани не определяют только по плотности.'],
 'bio-human-muscle-tissue':['Ткань состоит из поперечно исчерченных разветвлённых клеток, соединённых контактами; сокращения непроизвольные. Почему это не скелетная мышца?','Совокупность характерна для сердечной мышечной ткани. Скелетные волокна обычно длинные, многоядерные и не ветвятся таким образом. Поперечная исчерченность есть у обеих тканей, поэтому одного этого признака недостаточно.'],
 'bio-human-nervous-tissue':['Почему увеличение числа клеток нейроглии не заменит автоматически повреждённый проводящий путь из нейронов?','Нейроны имеют определённые связи и передают сигналы по аксонам и синапсам. Глия поддерживает, питает, защищает и изолирует нервные структуры, но просто увеличение её числа не воссоздаёт нужную сеть связей. Функция зависит от специализации и организации клеток.'],
 'bio-human-homeostasis':['После повышения температуры тела усилились потоотделение и кровоток в коже. Почему это отрицательная обратная связь?','Ответ увеличивает теплоотдачу и уменьшает исходное отклонение температуры. «Отрицательная» означает противодействие изменению, а не вредность реакции. При снижении отклонения необходимость в таком ответе уменьшается.'],
 'bio-human-skeleton':['Как S-образные изгибы позвоночника, сводчатая стопа и широкий таз связаны с прямохождением?','Позвоночник и своды стопы распределяют и смягчают механические нагрузки при шагах. Таз передаёт массу верхней части тела нижним конечностям и поддерживает органы. Эти признаки образуют согласованный комплекс опоры, а не независимые украшения скелета.'],
 'bio-human-bone':['После удаления минеральных солей кость стала гибкой, после выжигания органики — хрупкой. Что показывают опыты?','Органическая основа, прежде всего коллаген, обеспечивает упругость и сопротивление растяжению, минеральная часть — твёрдость и сопротивление сжатию. Механическая прочность нормальной кости возникает при совместном действии компонентов.'],
 'bio-human-joint':['Почему повреждение суставного хряща мешает движению, хотя сами кости и сокращающиеся мышцы сохранены?','Гладкий хрящ и синовиальная жидкость уменьшают трение и распределяют нагрузку между суставными поверхностями. При нарушении покрытия контакт становится менее благоприятным. Движение зависит не только от силы мышцы, но и от состояния соединения костей.'],
 'bio-human-muscle-work':['Почему удержание груза без перемещения может утомлять, хотя механическая работа груза равна нулю?','Мышца продолжает поддерживать напряжение, расходуя энергию на молекулярные процессы. Статическое напряжение также может ограничивать кровоток. Формула внешней механической работы не учитывает все внутренние энергозатраты живой ткани.'],
 'bio-human-movement-health':['Почему движение повреждённой конечности может усиливать вторичное повреждение окружающих тканей?','Отломки или нестабильные части смещаются относительно сосудов, нервов и мягких тканей. Поэтому ограничение лишних движений при оказании помощи имеет механическое основание. По одному внешнему виду нельзя надёжно определить все внутренние повреждения.'],
 'bio-human-internal-medium':['Как вещества из плазмы достигают клеток ткани и что происходит с избытком межклеточной жидкости?','Они проходят через стенку микрососудов и тканевую жидкость к клеткам. Избыток жидкости поступает в лимфатические капилляры и возвращается в венозное русло. Тканевая жидкость и лимфа связаны с плазмой, но не тождественны всей крови.'],
 'bio-human-blood':['Почему уменьшение числа эритроцитов может снизить доставку O₂, даже если лёгкие нормально вентилируются?','Меньше суммарного гемоглобина способно связать и перенести кислород. Вентиляция обеспечивает газ у дыхательной поверхности, а перенос к тканям зависит также от крови и кровотока. Лейкоциты выполняют защитные функции и не заменяют этот транспорт.'],
 'bio-human-clotting':['Чем образование фибрина отличается от склеивания эритроцитов при несовместимости крови?','При свёртывании растворимый фибриноген превращается в фибрин, образующий сеть с участием каскада факторов и тромбоцитов. Агглютинация эритроцитов связана с взаимодействием их антигенов и соответствующих антител. Это разные процессы.'],
 'bio-human-blood-groups':['Какие антигены ABO имеют эритроциты группы AB и почему её плазму нельзя считать подходящей любому получателю только по названию группы?','На эритроцитах AB есть антигены A и B; в обычной школьной модели плазма не содержит анти-A и анти-B. Совместимость клеточных компонентов и плазмы рассматривают в разных направлениях и учитывают другие системы. Универсальное правило для реального переливания из одной буквы группы не следует.'],
 'bio-human-heart':['Почему кровь при сокращении желудочка не должна возвращаться в предсердие?','Рост давления в желудочке закрывает створчатый клапан. Сухожильные нити и сосочковые мышцы препятствуют выворачиванию створок. Клапаны реагируют на разность давлений; они не перекачивают кровь самостоятельными сокращениями.'],
 'bio-human-cardiac-cycle':['Сердце сокращается 75 раз в минуту. В учебной схеме систола предсердий длится 0,1 с, желудочков — 0,3 с. Найдите длительность цикла и общей паузы.','Цикл 60/75 = 0,8 с. Общая пауза 0,8 − 0,1 − 0,3 = 0,4 с. Это условная схема при указанной частоте: при учащении сокращений длительности фаз меняются, особенно время расслабления.'],
 'bio-human-vessels':['Почему в капиллярах возможен эффективный обмен, а стенка аорты должна быть значительно прочнее?','Капиллярная стенка тонкая, а большая суммарная площадь русла связана с низкой линейной скоростью крови и временем для обмена. Аорта принимает кровь под высоким пульсирующим давлением; её эластические и прочные компоненты поддерживают поток и целостность.'],
 'bio-human-circuits':['Проследите путь эритроцита из левого желудочка к капиллярам мозга и затем к лёгким.','Левый желудочек → аорта → артерии мозга → капилляры → вены → верхняя полая вена → правое предсердие → правый желудочек → лёгочный ствол и лёгочные артерии → капилляры лёгких. До лёгких кровь пройдёт через правые отделы сердца.'],
 'bio-human-hemodynamics':['При одинаковом минутном объёме крови просвет большого числа артериол уменьшился. Как изменится сопротивление потоку и почему это влияет на давление?','Узкие сосуды сильнее сопротивляются течению, поэтому для того же потока нужна большая разность давлений. Реальный организм одновременно регулирует сердце и другие сосуды; условие фиксированного потока важно для вывода.'],
 'bio-human-airways':['Почему повреждение реснитчатого эпителия бронхов затрудняет удаление пыли?','Слизь задерживает частицы, а согласованные движения ресничек перемещают её к выходу из дыхательных путей. Без этого движения секрет с частицами удаляется хуже. Реснички не выполняют основной обмен кислорода с кровью — он происходит в альвеолах.'],
 'bio-human-alveoli':['Что произойдёт с диффузией газов при утолщении барьера между альвеолой и капилляром при прочих равных условиях?','Газам придётся преодолевать больший путь, скорость диффузии уменьшится. Тонкая стенка, большая площадь и градиент парциальных давлений поддерживают обмен. Увеличение числа дыхательных движений само по себе не устраняет утолщение барьера.'],
 'bio-human-resp-health':['Почему вдыхание частиц дыма может вредить и очищению дыхательных путей, и альвеолярному обмену?','Частицы и химические вещества повреждают эпителий и нарушают удаление слизи, вызывают воспалительные изменения. При поражении дыхательной поверхности ухудшается газообмен. Наличие кислорода во вдыхаемой смеси не делает все её компоненты безопасными для тканей.'],
 'bio-human-digestion-basics':['Почему тщательно измельчённая пища при прочих равных быстрее обрабатывается ферментами, а слюнная амилаза не расщепляет любой пищевой полимер?','Измельчение увеличивает доступную поверхность. Амилаза специфична к определённым связям в крахмале и не заменяет протеазы или ферменты расщепления целлюлозы. Механическая обработка и ферментативный гидролиз помогают друг другу, но различаются механизмом.'],
 'bio-human-stomach':['Зачем желудку одновременно кислота и слизистый защитный барьер?','Кислая среда способствует работе пепсина и превращению его предшественника в активную форму, влияет на белки пищи и микроорганизмы. Слизисто-бикарбонатный барьер защищает собственную поверхность желудка от этой среды и ферментов.'],
 'bio-human-small-intestine':['Почему желчь помогает перевариванию жиров, хотя не содержит основного набора пищеварительных ферментов?','Желчные компоненты эмульгируют жир и помогают образованию структур, необходимых для переноса продуктов переваривания. Это увеличивает доступность субстрата для липазы и способствует всасыванию. Непосредственный гидролиз связей осуществляет фермент, а не эмульгирование само по себе.'],
 'bio-human-absorption':['Различите первые пути всосавшейся глюкозы и основной части длинноцепочечных пищевых липидов из кишечной ворсинки.','Глюкоза поступает в кровеносные капилляры и далее через воротную вену к печени. Длинноцепочечные липиды после переработки в энтероцитах включаются в хиломикроны и поступают в лимфатический капилляр. Не все вещества из пищи сразу идут одним сосудистым путём.'],
 'bio-human-liver-colon':['Почему печень получает богатую всосавшимися веществами кровь из кишечника и одновременно артериальную кровь?','Воротная вена приносит вещества для переработки, запасания и обезвреживания; печёночная артерия участвует в снабжении кислородом. Функция печени требует и субстратов, и энергии. Желчь направляется в пищеварительный тракт по протокам, а не по воротной вене.'],
 'bio-human-urinary':['Проследите путь уже сформированной мочи от почки наружу. Какие органы не образуют первичную мочу?','Собирательные пути почки → чашечки и лоханка → мочеточник → мочевой пузырь → мочеиспускательный канал. Мочеточник проводит, пузырь накапливает. Первичная моча образуется фильтрацией в почечных тельцах, а не в пузыре.'],
 'bio-human-nephron':['Почему кровь после клубочка вновь поступает в капиллярную сеть около канальцев?','Первая сеть участвует в фильтрации под давлением. Вторая обеспечивает перенос при реабсорбции и секреции, связывая обработку фильтрата с кровью. Последовательность двух сетей соответствует двум различным задачам почки.'],
 'bio-human-skin':['Почему кровеносные сосуды и потовые железы относят к более глубоким слоям кожи, а наружный эпидермис не содержит собственных сосудов?','Эпидермис образует защитный эпителиальный барьер и получает питание диффузией из нижележащих тканей. В дерме находятся сосуды, нервные структуры и части кожных желёз. Название «кожа» включает несколько тканей, а не один слой одинаковых клеток.'],
 'bio-human-thermoregulation':['Почему при высокой влажности воздуха пот может стекать, но охлаждать хуже?','Тепло эффективно отводится при испарении воды, а высокая влажность уменьшает движущую силу испарения. Само выделение пота не равно его испарению. Поэтому одинаковый объём потоотделения не гарантирует одинаковую теплоотдачу.'],
 'bio-human-neuron-synapse':['На пресинаптическое окончание пришёл импульс, но выделение медиатора заблокировано. Почему следующая клетка может не получить сигнал?','В химическом синапсе электрическое событие должно вызвать выход медиатора, его диффузию и связывание с рецепторами следующей клетки. При остановке этого промежуточного этапа наличие импульса в первом нейроне не обеспечивает передачу через щель.'],
 'bio-human-reflex':['Человек отдёрнул руку до осознанного ощущения боли. Как это возможно и означает ли отсутствие участия головного мозга вообще?','Дуга отдёргивания может замкнуться через спинной мозг раньше осознанной обработки сигнала. Одновременно информация передаётся в головной мозг, где формируется ощущение и дальнейшая реакция. Быстрый ответ не означает, что сигнал никогда не достиг мозга.'],
 'bio-human-spinal':['Что различается при повреждении заднего и переднего корешка одного спинномозгового нерва?','Задний корешок проводит преимущественно чувствительные сигналы к спинному мозгу, передний — двигательные от него. Поэтому нарушаются разные направления передачи. После объединения корешков спинномозговой нерв становится смешанным.'],
 'bio-human-brain':['Почему нарушение координации движений связывают с мозжечком, а не с тем, что он непосредственно образует все мышечные импульсы?','Мозжечок сопоставляет и корректирует двигательные сигналы, участвует в равновесии и точности движений. Сокращение зависит от целой системы проводящих путей и двигательных нейронов. Повреждение звена согласования может нарушить движение при сохранённых мышцах.'],
 'bio-human-somatic-autonomic':['Сравните произвольное поднятие руки и изменение частоты сердцебиения при испуге. Каковы основные исполнительные органы?','Соматическая двигательная система управляет скелетными мышцами. Автономная регулирует сердце, гладкие мышцы и железы; симпатические и парасимпатические влияния часто действуют противоположно. Обе системы связаны с центральной нервной системой.'],
 'bio-human-glucose':['Почему после еды инсулин способствует снижению глюкозы крови, а при голодании глюкагон повышает её?','Инсулин способствует использованию и запасанию питательных веществ, включая синтез гликогена и захват глюкозы определёнными тканями. Глюкагон действует прежде всего на печень, усиливая процессы поступления глюкозы в кровь. Гормоны регулируют пути, а не превращаются сами в запасной углевод.'],
 'bio-human-analyzer':['Если рецепторы работают, но прерван соответствующий проводящий путь, достаточно ли рецепторного возбуждения для обычного осознанного ощущения?','Нет. Анализатор включает рецепторный, проводниковый и центральный отделы. Для нормального ощущения информация должна поступить к соответствующим структурам мозга и быть обработана. Работа одного отдела не гарантирует целостной функции.'],
 'bio-human-eye':['Почему слепое пятно не воспринимает свет, а жёлтое пятно обеспечивает высокую остроту центрального зрения?','В месте выхода зрительного нерва нет палочек и колбочек. В центральной области жёлтого пятна высока плотность колбочек и особая организация связей, позволяющая различать детали. Наличие светового изображения на участке сетчатки недостаточно без фоторецепторов.'],
 'bio-human-accommodation':['Как меняется хрусталик при переводе взгляда с далёкого объекта на близкий?','Ресничная мышца сокращается, натяжение связок уменьшается, хрусталик становится более выпуклым и сильнее преломляет свет. Это аккомодация. Она не равна изменению диаметра зрачка, которое прежде всего регулирует количество света.'],
 'bio-human-ear':['Как звуковое колебание превращается в нервный сигнал и где здесь роль слуховых косточек?','Барабанная перепонка и косточки передают колебания к овальному окну, движение жидкостей улитки вызывает смещение структур и изгиб волосков рецепторных клеток. Затем меняется сигнализация к слуховому нерву. Косточки передают механическое колебание, а не проводят нервный импульс.'],
 'bio-human-taste-smell':['Почему при нарушенном обонянии еда может казаться менее разнообразной по вкусу, хотя рецепторы языка сохранены?','Общее восприятие пищи объединяет вкус, запах, температуру и другие сигналы. Потеря обонятельного компонента уменьшает различение ароматов. Это не означает, что на языке исчезли все рецепторы основных вкусов.'],
 'bio-human-reflex-learning':['После многократного сочетания звука с пищей появился ответ на звук. Что произойдёт при длительном предъявлении звука без пищи?','Условная связь может угаснуть: сигнал перестаёт надёжно предсказывать подкрепление. Сам звук изначально не был пищей; обучение связало его с биологически значимым событием. Угасание не следует путать с повреждением слюнных желёз.'],
 'bio-human-higher-functions':['Почему реакция на слово «лимон» может отличаться от простого восприятия его звука?','Слово имеет усвоенное значение и связано с опытом, образами и другими понятиями. В школьном описании речь относится ко второй сигнальной системе. Физический звук и его смысл различаются; понимание зависит от обучения и контекста.'],
 'bio-human-sleep':['Почему сон не является полным выключением головного мозга?','Во сне сохраняется работа нервных сетей и регуляция жизненных функций, меняются активность и взаимодействие систем. Чередуются состояния с разными физиологическими признаками. Снижение внешней реакции не означает отсутствия внутренних процессов.'],
 'bio-human-male':['Почему семенники относят к железам смешанной функции, а образование сперматозоидов не тождественно синтезу тестостерона?','В семенных канальцах развивается мужская половая клеточная линия, а специализированные эндокринные клетки выделяют гормоны в кровь. Процессы взаимосвязаны регуляцией, но выполняются разными структурами и дают разные продукты.'],
 'bio-human-female-cycle':['На схеме после овуляции уровень прогестерона повысился. Какая структура стала его главным временным источником и каково действие на матку?','Жёлтое тело, образовавшееся из остатка фолликула. Прогестерон способствует переходу эндометрия в состояние, подходящее для имплантации, и его поддержанию. Овуляция происходит в яичнике, а подготовка слизистой — в матке.'],
 'bio-human-fertilization':['Почему первый митоз зиготы не является вторым оплодотворением?','При оплодотворении объединяется наследственный материал двух гамет и восстанавливается диплоидный набор. При митозе после репликации уже имеющийся генетический материал распределяется между дочерними клетками. Новый сперматозоид для каждого деления не нужен.'],
 'bio-human-implantation':['Почему плацента обеспечивает обмен, хотя материнская и плодная кровь обычно не смешиваются напрямую?','Обмен происходит через разделяющий их барьер: кислород и питательные вещества переходят к плоду, продукты обмена — в обратном направлении. Кровь плода движется по собственным сосудам. Барьер избирателен, но не является абсолютной защитой от всех веществ и возбудителей.'],
 'bio-human-development':['Почему клетки нервной системы и мышцы одного человека могут содержать почти одинаковый набор генов, но иметь разное строение?','При дифференцировке различаются активные гены и синтезируемые белки, формируются разные структуры и связи. Специализация обычно не требует удаления всех «лишних» генов. Генетическая информация реализуется по-разному в зависимости от состояния клетки.'],
 'bio-human-prevention':['Чем отличается устранение источника заражения от укрепления специфической иммунной памяти?','Первое уменьшает вероятность контакта с возбудителем и разрывает путь передачи. Иммунная память меняет скорость и характер ответа после распознавания соответствующего антигена. Меры воздействуют на разные звенья процесса и не являются полными заменами друг друга.'],
 'bio-human-experiments':['Пульс после нагрузки измерили у спортсменов сразу, а у другой группы через пять минут. Можно ли напрямую объяснить разницу тренированностью?','Нет: различалось время восстановления, которое само влияет на пульс. Нужны одинаковая нагрузка и момент измерения, исходные показатели, сопоставимость групп и повторы. Наблюдаемое различие не отделяет эффект тренированности от различия процедуры.'],
 'bio-human-exercise':['При нагрузке частота сердца 120/мин, ударный объём 90 мл. Найдите минутный объём и объясните, почему это ещё не равно потреблению кислорода.','120 × 90 = 10800 мл/мин = 10,8 л/мин крови. Потребление O₂ зависит также от содержания кислорода в артериальной крови и его извлечения тканями. Объём протекающей крови и объём использованного газа — разные величины.']
});

Object.assign(examples, {
 'bio-evolution-1-lesson':['Сравните объяснения: «жирафы вытягивали шею и передали удлинение потомкам» и «носители наследственных вариантов оставляли разное число потомков».','Первое соответствует идее наследования приобретённых упражнением изменений у Ламарка. Второе описывает естественный отбор наследственных вариантов в дарвиновской рамке; СТЭ связывает их с генетикой популяций. Отбор не создаёт необходимый признак по желанию особи.'],
 'bio-evolution-species':['Два внешне почти одинаковых вида птиц различаются брачными песнями и не образуют общих потомков. Почему морфологического критерия недостаточно?','Сходное строение не исключает репродуктивной изоляции. Нужно сопоставлять также поведение, генетические, экологические и другие данные. Для вида-двойника внешние признаки могут быть очень близки; любой один критерий имеет ограничения.'],
 'bio-evolution-selection':['После серии холодных зим доля наследственно более густошёрстных особей выросла. Как проверить объяснение движущим отбором?','Нужно показать наследственные различия, их связь с выживанием или числом потомков и изменение распределения признака в поколениях. Простое отрастание зимней шерсти у тех же особей — сезонное изменение и само по себе не доказывает эволюционный сдвиг.'],
 'bio-evolution-adaptation':['Почему покровительственная окраска, полезная на тёмной коре, может стать невыгодной после изменения фона?','Хищники обнаруживают добычу относительно конкретной среды. При смене фона меняется заметность наследственных вариантов, а с ней может измениться репродуктивный успех. Приспособленность относительна, а признак не является полезным при любых условиях.'],
 'bio-evolution-3-lesson':['Сравните переднюю конечность лошади и крыло летучей мыши; затем крыло насекомого и крыло птицы.','В первом случае общий план и происхождение конечности при разных функциях указывают на гомологию. Во втором полёт выполняют структуры разного происхождения — это аналогия как органов полёта. Критерий происхождения отделяют от сходства функции.'],
 'bio-evolution-evidence':['На дереве A и B имеют более недавнего общего предка, чем с C. Изменится ли родство, если повернуть ветвь вокруг узла и переставить подписи концов визуально?','Нет, если связи узлов сохранены. Родство определяет общий предок, а не расстояние между надписями на странице. Современная A также не обязана быть предком современной B: обе могут происходить от общей предковой популяции.'],
 'bio-evolution-directions':['У паразитической линии редуцировалась пищеварительная система, но выросли численность и ареал. Противоречат ли друг другу эти изменения?','Нет. Упрощение отдельных органов может сопровождаться успешным размножением в новой среде. Биологический прогресс оценивают по численности, ареалу и разнообразию линии, а не только по сложности каждого органа. В школьной классификации редукцию связывают с общей дегенерацией.'],
 'bio-evolution-endosymbiosis':['Почему собственная ДНК и деление митохондрий поддерживают эндосимбиотическую модель, но не делают их независимыми бактериями современной клетки?','Эти признаки согласуются с происхождением от клеточного симбионта. За историю часть функций и генов стала зависеть от хозяина; многие белки поступают из цитоплазмы. Современная митохондрия — интегрированный органоид, и один её признак не воспроизводит всю предковую организацию.'],
 'bio-evolution-phylogeny':['Почему семя и пыльцевая трубка расширили возможности освоения суши по сравнению с размножением папоротника?','Пыльцевая трубка переносит мужские гаметы без наружной плёнки воды. Семя защищает зародыш, содержит запас и помогает переживать неблагоприятный период. У папоротника подвижным сперматозоидам для достижения яйцеклетки обычно нужна вода.'],
 'bio-evolution-human-system':['Почему сходство кисти человека и других приматов — довод о родстве, а не доказательство происхождения человека от современной обезьяны?','Сходный план отражает общую эволюционную историю. Современные виды приматов представляют разные сохранившиеся ветви; человек и другие человекообразные имеют общих предков. Родство не требует, чтобы один ныне живущий вид был прямым предком другого.'],
 'bio-evolution-4-lesson':['Почему находки разных древних форм человека нельзя автоматически выстроить в ряд, где каждая следующая произошла от предыдущей?','Некоторые формы сосуществовали и могли принадлежать разным ветвям. Для гипотезы предковой связи нужны возраст, признаки, география и другие данные. Само сходство и последовательность находок не доказывают единственную линейную цепь происхождения.'],
 'bio-evolution-human-factors':['Как обучение изготовлению орудий могло взаимодействовать с биологическими факторами антропогенеза?','Навык передавался через обучение и общение, менял получение ресурсов и условия жизни. Наследственные различия продолжали влиять на выживание и размножение. Культурная передача приобретённого навыка не равна записи этого навыка в последовательность ДНК.'],
 'bio-evolution-human-diversity':['Почему географические различия пигментации кожи не разделяют современных людей на биологические виды или «высшие» и «низшие» группы?','Все современные люди принадлежат одному виду, популяции связаны происхождением и обменом генами. Внешние признаки изменяются непрерывно и отражают лишь часть разнообразия. Они не задают иерархию достоинства или способностей и не доказывают репродуктивной изоляции.'],
 'bio-ecology-1-lesson':['Два вида птиц живут в одном лесу, но один добывает насекомых под корой, другой — в кроне. Совпадают ли их местообитание и ниша?','Общее местообитание может совпадать, но используемые ресурсы и способы питания различаются. Экологическая ниша включает требования и функциональные связи вида, а не только адрес его присутствия.'],
 'bio-ecology-population-structure-lesson':['На участке 4 га учтено 120 особей, на участке 10 га — 200. Где выше плотность и почему численность даёт иной порядок?','Плотности 120/4 = 30 и 200/10 = 20 особей/га; выше на первом участке. Абсолютная численность выше на втором. Для сравнения обеспеченности пространством нужен общий знаменатель, а для прогноза дополнительно важны ресурсы и структура популяции.'],
 'bio-ecology-2-lesson':['Синица заняла дупло, созданное дятлом; заметного влияния на дятла не обнаружено. Чем это отличается от паразитизма?','В описанных условиях одна сторона получает убежище, а другой не показаны польза или ущерб — пример комменсализма, квартирантства. При паразитизме паразит использует хозяина с ущербом для него. Знак отношения определяют по последствиям, а не по одному соседству.'],
 'bio-ecology-community-lesson':['После удаления конкурента вид занял более широкий диапазон глубин. Как соотносятся потенциальная и реализованная ниши?','Без конкурента стал доступен участок условий, пригодных виду физиологически. Реализованная ниша при взаимодействиях может быть уже потенциальной. Опыт показывает действие конкуренции в данных условиях, но не устанавливает все границы потенциальной ниши.'],
 'bio-ecology-ecosystem-lesson':['Почему аквариум с рыбами и растениями нельзя считать системой, где энергия бесконечно ходит по кругу?','Свет или органический корм приносят энергию извне, организмы используют её и рассеивают как тепло. Атомы веществ могут многократно переходить между компонентами, но для поддержания процессов нужен новый приток пригодной энергии.'],
 'bio-ecology-food-web-lesson':['В цепи трава → кузнечик → лягушка → уж кого называют консументом второго порядка? Что означает стрелка?','Лягушку: она поедает первичного консумента — кузнечика. Стрелка направлена от съедаемого объекта к потребителю и показывает перенос вещества и энергии. Уж здесь консумент третьего порядка, хотя занимает четвёртый трофический уровень.'],
 'bio-ecology-3-lesson':['Почему сжигание ископаемого топлива может увеличивать атмосферный CO₂ быстрее, чем современная растительность связывает дополнительный углерод?','Быстро высвобождается углерод, накопленный и изолированный от быстрого обмена за длительное время. Поглощение современными экосистемами ограничено условиями и продуктивностью. Наличие фотосинтеза не гарантирует мгновенного равенства нового выброса и поглощения.'],
 'bio-ecology-succession-lesson':['На голой лаве и на заброшенном поле началось заселение растениями. Почему пути и скорость восстановления отличаются?','На лаве обычно нет готовой почвы и местного запаса семян — первичная сукцессия начинается с формирования условий. На поле сохранены почва и часть организмов или зачатков — вторичная сукцессия использует это наследие. Конкретная скорость зависит также от климата и источников расселения.'],
 'bio-ecology-stability-lesson':['Две экосистемы одинаково изменились при засухе, но одна быстро восстановилась. Какое свойство различалось?','Способность к восстановлению после воздействия. Сопротивляемость исходному изменению и скорость возвращения функций — разные стороны устойчивости. Разнообразие может помогать замещению функций, но само число видов не гарантирует одинаковую реакцию на любую угрозу.'],
 'bio-ecology-eutrophication-lesson':['После притока удобрений сначала выросла масса водорослей, затем ночью участились заморы рыбы. Постройте причинную цепь.','Избыток биогенов стимулировал рост; дыхание организмов и разложение отмершей органики увеличили расход O₂. Ночью фотосинтез не восполняет кислород, дефицит усиливается. Удобрение не обязано непосредственно отравлять рыбу, чтобы вызвать этот эффект.'],
 'bio-ecology-conservation-lesson':['Редкий вид сохранился в двух маленьких участках леса, разделённых дорогами. Чем может помочь экологический коридор и чего он не гарантирует?','Он может облегчить расселение и обмен генами, уменьшив изоляцию популяций. Но без подходящего качества местообитаний и контроля других угроз один коридор не гарантирует восстановления численности. Меру оценивают по данным о реальном использовании и результатах.'],
 'bio-ecology-field-experiment-lesson':['Для оценки удобрения обработали один луг и сравнили с другим лугом в иной климатической зоне. Почему вывод об эффекте удобрения слаб?','Одновременно различаются климат, почва и история участков; они могут объяснять результат. Нужны сопоставимые площадки с контролем, независимыми повторами и распределением воздействия. Много измерений травинок на одном лугу не создаёт независимые повторы обработки.'],
 'bio-ecology-integration-lesson':['В пруду исчез хищник, поедающий мелкую рыбу; затем уменьшился зоопланктон и увеличилось количество водорослей. Предложите объяснение и его проверку.','Мелкая рыба могла стать многочисленнее и сильнее выедать зоопланктон; уменьшение поедания водорослей дало им преимущество. Это гипотеза трофического каскада. Нужно измерить звенья цепи и проверить альтернативы, включая поступление биогенов и изменение освещения.']
});

const generic = b => b.type==='ege_example' && /Как (построить|дать)|Объясните значение одного/.test(b.content.prompt);
function refine(course){
 const all=course.sections.flatMap(s=>s.topics.flatMap(t=>t.lessons||[t.lesson].filter(Boolean)));
 for(const section of course.sections)for(const topic of section.topics)for(const lesson of topic.lessons||[topic.lesson].filter(Boolean)){
  if(!lesson.blocks.some(generic))continue;
  const real=lesson.blocks.some(b=>b.type==='ege_example'&&!generic(b));
  if(real&&!examples[lesson.slug]){lesson.blocks=lesson.blocks.filter(b=>!generic(b));lesson.contentStatus='review';continue;}
  if(!examples[lesson.slug])continue;
  const [prompt,answer]=examples[lesson.slug];
  lesson.blocks=lesson.blocks.map(b=>generic(b)?{type:'ege_example',content:{prompt,answer}}:b);
  lesson.contentStatus='review';
 }
 const movements=all.find(l=>l.slug==='bio-diversity-4-plant-physiology-lesson-2');
 const comparison=movements.blocks.find(b=>b.type==='comparison');
 comparison.content={title:'Тропизм, настия, таксис',items:[
  ['Тропизм','Направление роста зависит от направления раздражителя','Изгиб побега к боковому свету'],
  ['Настия','Направление движения задаётся устройством органа, а не направлением раздражителя','Складывание листьев мимозы при прикосновении; механизм может быть тургорным'],
  ['Таксис','Перемещение всей подвижной клетки или организма относительно раздражителя','Фототаксис эвглены']
 ]};
 const leaf=all.find(l=>l.slug==='bio-diversity-4-plant-leaf-lesson');
 const leafText=leaf.blocks.find(b=>b.type==='text'&&b.content.text.startsWith('Связь целого растения:'));
 const defense='Защита растений сочетает механические барьеры — кутикулу, прочные стенки, волоски и колючки — с химическими веществами. Фитонциды способны подавлять определённые микроорганизмы; их действие зависит от вещества и условий, а не означает стерильность всего растения. Выделение у растений не требует отдельной системы органов как почки: газы и водяной пар выходят через поверхности, вещества могут накапливаться в вакуолях и удаляться с опадающими листьями, выделяться корнями и специальными структурами. Гуттация — выход капель жидкой воды с растворёнными веществами через гидатоды; это не испарение при транспирации.';
 if(!leafText.content.text.includes('Фитонциды'))leafText.content.text+='\n\n'+defense;
 leaf.contentStatus='review';
 const optional={
  'bio-science-2-lesson':'В проекте кодификатора ФИПИ-2027 метаанализ и понятие статистического теста выделены курсивом: они даны здесь как дополнительный контекст. Переменные, выборка, контроль и оценка достоверности остаются частью проверяемого ядра.',
  'bio-cell-3-lesson':'В проекте кодификатора ФИПИ-2027 теломеры, теломераза, регуляция митотического цикла и апоптоз выделены курсивом. Эти пояснения дополнительны; фазы, репликация и подсчёт хромосом и ДНК остаются экзаменационным ядром.',
  'bio-molecular-3-lesson-3':'Гипотеза оперона выделена курсивом в проекте кодификатора ФИПИ-2027. Разбор её механизма дан дополнительно; генетический код, транскрипция и трансляция входят в проверяемый материал.',
  'bio-genetics-1-lesson-3':'В проекте кодификатора ФИПИ-2027 комплементарность и эпистаз выделены курсивом, а полимерия — нет. Примеры первых двух моделей относятся к дополнительной глубине; полимерию не следует исключать из подготовки.',
  'bio-genetics-3-lesson':'В проекте кодификатора ФИПИ-2027 внеядерное наследование выделено курсивом. Цитоплазматические мутации при этом перечислены среди проверяемых видов мутаций. Подробности гетероплазмии — расширение, а не обязательная универсальная схема наследования.'
 };
 for(const [slug,value]of Object.entries(optional)){
  const lesson=all.find(l=>l.slug===slug);
  if(!lesson.blocks.some(b=>b.type==='deep_dive'&&b.content.text===value)){
   const firstExtra=lesson.blocks.findIndex(b=>b.type==='heading'&&/Повторы:|Теломеры|Оперон|Ядерная и цитоплазматическая|Кумулятивная|Полимерия/.test(b.content.text));
   const summary=lesson.blocks.findIndex(b=>b.type==='summary');
   // Put the note outside contiguous foundation supplements, which stay reproducible.
   lesson.blocks.splice(firstExtra>=0?firstExtra:summary,0,{type:'deep_dive',content:{label:'Глубже ЕГЭ',text:value}});
  }
 }
 for(const lesson of all){
  if(lesson.slug==='bio-evolution-factors')for(const block of lesson.blocks)if(block.type==='text')block.content.text=block.content.text.replace('изменения ДНК происходят до встречи с фактором среды; среда лишь меняет судьбу носителей','изменения ДНК не направлены на удовлетворение будущей потребности. Они могут возникать до или после изменения условий; некоторые факторы повышают частоту мутаций, но не гарантируют полезный результат. Отбор меняет судьбу наследственных вариантов');
  if(lesson.slug==='bio-evolution-human-system')for(const block of lesson.blocks)if(block.type==='text')block.content.text=block.content.text.replace('жаберные щели глотки','глоточные дуги и карманы');
  if(lesson.slug==='bio-evolution-phylogeny')for(const block of lesson.blocks)if(block.type==='comparison')for(const row of block.content.items)if(row[0]==='спора')row[1]='обычно одна клетка; нет многоклеточного зародыша и питающей ткани семени';
  for(const block of lesson.blocks)if(block.type==='deep_dive'&&['Приоритет подготовки к ЕГЭ-2027','Дополнительно к экзаменационному ядру'].includes(block.content.label))block.content.label='Глубже ЕГЭ';
 }
 const refinements={
  'bio-evolution-species':['Вид —','Биологический критерий через скрещивание прежде всего применим к половым формам. Для бактерий, бесполых организмов и ископаемых видов используют другие сочетания данных: генетические, морфологические, экологические и исторические. Это ограничение определения, а не отсутствие видов у таких организмов.'],
  'bio-evolution-evidence':['Палеонтология','Эндемик встречается естественно в ограниченной области; реликт сохранился от более широко распространённой в прошлом группы или сообщества. Биогеографические области выделяют по составу и истории биоты, а не только по современным государственным границам. В классической схеме шести зоогеографических областей различают Палеарктическую, Неарктическую, Неотропическую, Эфиопскую, Индо-Малайскую (Ориентальную) и Австралийскую. Современные схемы могут уточнять их границы и число; в задании следуют указанной карте.'],
  'bio-evolution-4-lesson':['Неандертальцы','Гейдельбергский человек (Homo heidelbergensis) — название ряда среднеплейстоценовых находок, которые в традиционной учебной схеме связывают с предками неандертальцев и Homo sapiens. Круг относимых к нему находок и точные родственные связи обсуждаются; его не следует изображать бесспорной единственной ступенью для всех поздних линий.'],
  'bio-evolution-human-diversity':['Историческая школьная','В исторической учебной классификации употребляются названия европеоидная (евразийская), австрало-негроидная (экваториальная) и монголоидная (азиатско-американская) большие расы. Это термины прежних описательных схем внешних признаков, присутствующие в кодификаторе, а не отдельные виды, чёткие генетические границы или научная иерархия человеческих групп.']
 };
 for(const [slug,[start,value]]of Object.entries(refinements)){
  const block=all.find(l=>l.slug===slug).blocks.find(b=>b.type==='text'&&b.content.text.startsWith(start));
  if(!block.content.text.includes(value))block.content.text+='\n\n'+value;
 }
 for(const lesson of all){
  const words=JSON.stringify(lesson.blocks).split(/\s+/).length;
  lesson.minutes=Math.max(lesson.minutes||1,Math.ceil(words/160));
 }
 // All 17 evolution lessons were reread as a complete group; specific corrections
 // and the scope of this editorial review are recorded in COMPLETENESS_REVIEW.md.
 // This retains the existing evolution publication gate without claiming FIPI certification.
 for(const topic of course.sections.find(s=>s.slug==='biology-evolution').topics)for(const lesson of topic.lessons||[topic.lesson].filter(Boolean))lesson.contentStatus='verified';
 return course;
}
if(require.main===module){
 const file=path.resolve(__dirname,'../content/biology/course.json');
 fs.writeFileSync(file,JSON.stringify(refine(JSON.parse(fs.readFileSync(file,'utf8'))),null,2)+'\n');
 console.log('Concrete example definitions: '+Object.keys(examples).length);
}
module.exports={refine,examples,generic};
